            ap.user_data = ds->srtp;
            pj_sockaddr_cp(&ds->rem_addr, &info.src_rtp_name);
            pj_sockaddr_cp(&ap.rem_addr, &ds->rem_addr);
            ap.addr_len = pj_sockaddr_get_len(&ap.rem_addr);
