    g_hash_table_iter_init(&iter, pfs);
    while (g_hash_table_iter_next (&iter, &key, NULL)) {
        const gchar* id = key;
        g_string_append_printf(s, "After=sys-subsystem-net-devices-%s.device\n", id);
